"use client";

import { useEffect, useRef } from "react";
import { useInView } from "react-intersection-observer";
import { Loader2 } from "lucide-react";
import {
  DataViewToolbar,
  type FileFormat,
} from "../data-view-criteria/data-view-toolbar";
import { DataViewEmpty } from "../data-view-criteria/data-view-empty";
import { DataTimelineGroup } from "./data-timeline-group";
import { DataTimelineItem } from "./data-timeline-item";
import { DataTimelineSkeleton } from "./data-timeline-skeleton";
import type { UseCriteriaTimelineReturn } from "@/types/use-criteria-timeline.type";
import { cn } from "@/lib/utils";

interface DataTimelineCriteriaProps<T> {
  /**
   * Timeline state from useCriteriaTimeline
   */
  timeline: UseCriteriaTimelineReturn<T>;

  /**
   * Render function for each timeline event
   * Receives the item, index within group, and whether it's the last item
   */
  renderEvent: (item: T, index: number, isLast: boolean) => React.ReactNode;

  /**
   * Custom icon for timeline markers
   * Can be a function that receives the item and returns a ReactNode
   */
  getIcon?: (item: T) => React.ReactNode;

  /**
   * Placeholder text for search input
   * @default "Search events..."
   */
  searchPlaceholder?: string;

  /**
   * Empty state message
   * @default "No events found."
   */
  emptyMessage?: string;

  /**
   * Custom action bar (e.g., buttons, filters)
   */
  actionBar?: React.ReactNode;

  /**
   * Export function for different formats
   */
  onExport?: (format: FileFormat) => Promise<string> | string;

  /**
   * Whether to show relative time labels (e.g., "Today", "Yesterday")
   * @default true
   */
  showRelativeLabels?: boolean;
  toolbarLayout?: "default" | "none";

  /**
   * Custom className for the container
   */
  className?: string;
}

export function DataTimelineCriteria<T>({
  timeline,
  renderEvent,
  getIcon,
  searchPlaceholder = "Search...",
  emptyMessage = "No events found.",
  actionBar,
  onExport,
  showRelativeLabels = true,
  toolbarLayout = "default",
  className,
}: DataTimelineCriteriaProps<T>) {
  const {
    groupedData,
    isLoading,
    filterProps,
    searchProps,
    loadMore,
    hasMore,
    isLoadingMore,
  } = timeline;

  // Ref to prevent multiple simultaneous fetches
  const isFetchingRef = useRef(false);

  const { ref: inViewRef, inView } = useInView({
    threshold: 0,
    rootMargin: "100px",
    triggerOnce: false,
  });

  useEffect(() => {
    if (inView && hasMore && !isLoadingMore && !isFetchingRef.current) {
      isFetchingRef.current = true;
      loadMore();
    }
  }, [inView, hasMore, isLoadingMore, loadMore]);

  // Reset the fetching ref when element goes out of view
  useEffect(() => {
    if (!inView && !isLoadingMore) {
      isFetchingRef.current = false;
    }
  }, [inView, isLoadingMore]);

  const isEmpty = !isLoading && groupedData.length === 0;
  const hasData = groupedData.length > 0;

  const showToolbar = toolbarLayout !== "none";

  // Timeline content JSX
  const timelineContent = (
    <>
      {isLoading && <DataTimelineSkeleton count={3} />}

      {isEmpty && <DataViewEmpty message={emptyMessage} />}

      {hasData && (
        <div className="space-y-8">
          {groupedData.map((group) => (
            <DataTimelineGroup
              key={group.date}
              group={group}
              showRelativeLabel={showRelativeLabels}
              renderItem={(item, itemIndex, isLast) => (
                <DataTimelineItem
                  key={itemIndex}
                  isLast={isLast}
                  icon={getIcon?.(item)}
                >
                  {renderEvent(item, itemIndex, isLast)}
                </DataTimelineItem>
              )}
            />
          ))}

          {hasMore && (
            <div ref={inViewRef} className="flex justify-center py-8">
              {isLoadingMore && (
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <Loader2 className="h-4 w-4 animate-spin" />
                  <span>Loading more events...</span>
                </div>
              )}
            </div>
          )}

          {!hasMore && !isLoading && (
            <div className="flex justify-center py-8 text-sm text-muted-foreground">
              <span>✨ You&apos;ve reached the end</span>
            </div>
          )}
        </div>
      )}
    </>
  );

  // Vertical layout (default)
  if (toolbarLayout === "default" || toolbarLayout === "none") {
    return (
      <div className={cn("space-y-6", className)}>
        {showToolbar && (
          <DataViewToolbar
            queryFilter={filterProps.queryFilter}
            criteria={timeline.criteria}
            actionBar={actionBar}
            onExport={onExport}
            searchProps={{
              ...searchProps,
              searchPlaceholder,
            }}
          />
        )}
        {timelineContent}
      </div>
    );
  }

  return (
    <div className={cn("flex h-screen gap-6", className)}>
      <div
        className={cn(
          "w-80 shrink-0 overflow-y-auto border-r p-6 scroll-smooth",
          "scrollbar-thin scrollbar-track-transparent scrollbar-thumb-border"
        )}
      >
        <DataViewToolbar
          queryFilter={filterProps.queryFilter}
          criteria={timeline.criteria}
          actionBar={actionBar}
          onExport={onExport}
          searchProps={{
            ...searchProps,
            searchPlaceholder,
          }}
        />
      </div>

      <div
        className={cn(
          "flex-1 overflow-y-auto p-6 scroll-smooth",
          "scrollbar-thin scrollbar-track-transparent scrollbar-thumb-border"
        )}
      >
        {timelineContent}
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import type { TimelineGroup } from "@/types/use-criteria-timeline.type";
import { Badge } from "@/components/ui/badge";

interface DataTimelineGroupProps<T> {
  /**
   * The timeline group data
   */
  group: TimelineGroup<T>;

  /**
   * Render function for each item in the group
   */
  renderItem: (item: T, index: number, isLast: boolean) => React.ReactNode;

  /**
   * Custom className for the group container
   */
  className?: string;

  /**
   * Whether to show the relative label (e.g., "Today", "2 hours ago")
   * @default true
   */
  showRelativeLabel?: boolean;
}

export function DataTimelineGroup<T>({
  group,
  renderItem,
  className,
  showRelativeLabel = true,
}: DataTimelineGroupProps<T>) {
  return (
    <div className={cn("space-y-4", className)}>
      {/* Group header */}
      <div className="flex items-center gap-3 sticky top-0 bg-background/95 backdrop-blur supports-backdrop-filter:bg-background/60 z-10 py-2">
        <h3 className="text-sm font-semibold text-foreground">{group.label}</h3>
        {showRelativeLabel && group.relativeLabel && (
          <Badge variant="secondary" className="text-xs">
            {group.relativeLabel}
          </Badge>
        )}
        <div className="flex-1 border-b" />
        <span className="text-xs text-muted-foreground">
          {group.items.length} {group.items.length === 1 ? "item" : "items"}
        </span>
      </div>

      {/* Timeline items */}
      <div className="space-y-0">
        {group.items.map((item, index) =>
          renderItem(item, index, index === group.items.length - 1)
        )}
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";

interface DataTimelineItemProps {
  /**
   * The content to render inside the timeline item
   */
  children: React.ReactNode;

  /**
   * Whether this is the last item in the group
   */
  isLast?: boolean;

  /**
   * Custom className for the container
   */
  className?: string;

  /**
   * Custom icon/dot for the timeline marker
   */
  icon?: React.ReactNode;
}

export function DataTimelineItem({
  children,
  isLast = false,
  className,
  icon,
}: DataTimelineItemProps) {
  return (
    <div className={cn("relative pb-6 last:pb-0", className)}>
      {!isLast && (
        <div className="absolute left-3 top-6 bottom-0 w-0.5 bg-border" />
      )}

      <div className="absolute left-0 top-1.5">
        {icon ? (
          <div className="flex size-6 shrink-0 items-center justify-center rounded-full border-2 border-background bg-primary text-primary-foreground">
            {icon}
          </div>
        ) : (
          <div className="h-4 w-4 rounded-full border-2 border-background bg-primary" />
        )}
      </div>

      <div className="ml-8">{children}</div>
    </div>
  );
}

"use client";

import { Skeleton } from "@/components/ui/skeleton";

interface DataTimelineSkeletonProps {
  /**
   * Number of skeleton items to render
   * @default 3
   */
  count?: number;
}

export function DataTimelineSkeleton({ count = 3 }: DataTimelineSkeletonProps) {
  return (
    <div className="space-y-8">
      {Array.from({ length: count }).map((_, groupIndex) => (
        <div key={groupIndex} className="space-y-4">
          {/* Group header */}
          <div className="flex items-center gap-3">
            <Skeleton className="h-4 w-32" />
            <Skeleton className="h-4 w-20" />
          </div>

          {/* Timeline items */}
          <div className="space-y-4 pl-4 border-l-2 border-muted ml-2">
            {Array.from({ length: 2 }).map((_, itemIndex) => (
              <div key={itemIndex} className="relative pl-6">
                {/* Timeline dot */}
                <Skeleton className="absolute left-[-9px] top-2 h-4 w-4 rounded-full" />

                {/* Content */}
                <div className="space-y-2">
                  <Skeleton className="h-5 w-3/4" />
                  <Skeleton className="h-4 w-full" />
                  <Skeleton className="h-4 w-2/3" />
                  <div className="flex gap-2 mt-3">
                    <Skeleton className="h-6 w-16" />
                    <Skeleton className="h-6 w-16" />
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "../../ui/dropdown-menu";
import { Button } from "../../ui/button";
import { Filter as FilterIcon } from "lucide-react";
import { DataViewFilterPopover } from "./data-view-filter-popover";
import { DataViewFilterRow } from "./data-view-filter-row";
import { Badge } from "@/components/ui/badge";
import type { QueryFilter } from "@/lib/filter-utils";
import type { UseCriteriaReturn } from "@/types/use-criteria.type";

/**
 * Props for Filter component integration
 */
export interface FilterIntegrationProps {
  queryFilter: QueryFilter[];
  criteria: UseCriteriaReturn<any>; // eslint-disable-line @typescript-eslint/no-explicit-any
}

/**
 * Props for Search integration
 */
export interface SearchIntegrationProps {
  searchValue: string;
  onSearchChange: (value: string) => void;
  searchPlaceholder?: string;
  showSearch: boolean;
}

export function DataViewFilter({
  queryFilter,
  criteria,
}: FilterIntegrationProps) {
  const filtersCount = criteria.filters.length;
  const hasFilters = filtersCount > 0;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="sm" className="h-8 relative">
          <FilterIcon className="h-4 w-4" />
          Filter
          {hasFilters && (
            <Badge className="text-[10px] rounded bg-secondary size-[18px] text-foreground">
              {filtersCount}
            </Badge>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent className="w-[450px] p-4" align="start">
        {!hasFilters ? (
          <div className="space-y-0.5 mb-4">
            <p className="font-semibold">No filters applied</p>
            <p className="text-sm text-muted-foreground">
              Add filters to your query
            </p>
          </div>
        ) : (
          <div className="space-y-4 mb-4">
            <p className="font-semibold">Filters</p>
            <DataViewFilterRow fields={queryFilter} criteria={criteria} />
          </div>
        )}
        <DataViewFilterPopover fields={queryFilter} criteria={criteria} />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import * as React from "react";
import {
  ListFilter,
  Search,
  Type,
  Hash,
  Calendar,
  ToggleLeft,
  X,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  type FieldPath,
  type FilterOperator,
  type FilterValueFor,
  type OperatorsForType,
  isValidOperatorForType,
} from "@woltz/rich-domain";
import type { UseCriteriaReturn } from "@/types/use-criteria.type";
import { cn } from "@/lib/utils";
import { FilterBooleanValue } from "@/components/filter/filter-boolean-value";
import { FilterDateValue } from "@/components/filter/filter-date-value";
import { FilterOperatorSelector } from "@/components/filter/filter-operator-selector";
import { FilterValueSelector } from "@/components/filter/filter-value-selector";
import {
  type QueryFilter,
  type FilterType,
  type FilterValue,
  getDefaultOperator,
  operatorIsBetween,
  defineDefaultFilterValue,
  operatorRequiresValue,
} from "@/lib/filter-utils";

interface FilterProps {
  fields: QueryFilter[];
  criteria: UseCriteriaReturn<any>; // eslint-disable-line @typescript-eslint/no-explicit-any
}

const TYPE_ICONS: Record<FilterType, React.ReactNode> = {
  string: <Type className="h-4 w-4" />,
  number: <Hash className="h-4 w-4" />,
  date: <Calendar className="h-4 w-4" />,
  boolean: <ToggleLeft className="h-4 w-4" />,
};

export function DataViewFilterPopover({ fields, criteria }: FilterProps) {
  const [addFilterStep, setAddFilterStep] = React.useState<
    null | "field" | "value"
  >(null);
  const [search, setSearch] = React.useState("");
  const [selectedFieldForAdd, setSelectedFieldForAdd] =
    React.useState<QueryFilter | null>(null);
  const [tempOperator, setTempOperator] =
    React.useState<FilterValue["operator"]>("equals");
  const [tempValue, setTempValue] = React.useState<FilterValue["value"]>(null);

  const usedFields = criteria.filters.map((filter) => filter.field);
  const remainingFields = fields.filter(
    (field) => !usedFields.includes(field.field)
  );

  const HAS_FIELDS_REMAINING = remainingFields.length > 0;

  const filteredRemainingFields = remainingFields.filter((field) =>
    field.fieldLabel.toLowerCase().includes(search.toLowerCase())
  );

  const handleSelectFieldForAdd = (field: QueryFilter) => {
    setSelectedFieldForAdd(field);
    const defaultOp = getDefaultOperator(field.type);
    setTempOperator(defaultOp);

    const defaultDateRange = [
      new Date().toISOString(),
      new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString(),
    ];

    const defaultValue = operatorIsBetween(defaultOp)
      ? field.type === "number"
        ? [0, 0]
        : field.type === "date"
          ? defaultDateRange
          : ["", ""]
      : defineDefaultFilterValue(field.type, defaultOp);

    setTempValue(defaultValue);
    setSearch("");
    setAddFilterStep("value");
  };

  const onSelectOperator = (op: FilterOperator) => {
    if (!selectedFieldForAdd) return;

    const defaultDateRange = [
      new Date().toISOString(),
      new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString(),
    ];
    const defaultValue =
      selectedFieldForAdd.type === "date"
        ? defaultDateRange
        : selectedFieldForAdd.type === "number"
          ? [0, 0]
          : ["", ""];

    const prevOperatorIsBetween = operatorIsBetween(tempOperator);
    const newOperatorIsBetween = operatorIsBetween(op);

    setTempOperator(op);

    if (!operatorRequiresValue(op)) {
      setTempValue(null);
    } else if (!prevOperatorIsBetween && newOperatorIsBetween) {
      setTempValue(defaultValue);
    } else if (prevOperatorIsBetween && !newOperatorIsBetween) {
      setTempValue(defineDefaultFilterValue(selectedFieldForAdd.type, op));
    }
  };

  const handleConfirmAddFilter = () => {
    if (!selectedFieldForAdd || tempValue === null) return;

    criteria.addOrReplaceByIndex({
      field: selectedFieldForAdd.field as FieldPath<unknown>,
      operator: tempOperator as OperatorsForType<never>,
      value: tempValue as FilterValueFor<never>,
    });

    setAddFilterStep(null);
    setSelectedFieldForAdd(null);
    setTempOperator("equals");
    setTempValue(null);
  };

  const handleCancelAddFilter = () => {
    setAddFilterStep(null);
    setSelectedFieldForAdd(null);
    setTempOperator("equals");
    setTempValue(null);
    setSearch("");
  };

  const canAddFilter = React.useMemo(() => {
    if (!selectedFieldForAdd) return false;
    return isValidOperatorForType(tempValue, tempOperator);
  }, [tempValue, tempOperator, selectedFieldForAdd]);

  const STEP_VALUE_ADD_FILTER_BUTTON_DISABLED =
    !canAddFilter || tempValue === null || tempValue === "";

  return (
    <div className="flex items-center gap-2">
      <Popover
        open={addFilterStep !== null}
        onOpenChange={(open) => !open && handleCancelAddFilter()}
      >
        <PopoverTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            className="h-8 gap-1.5 bg-transparent"
            disabled={!HAS_FIELDS_REMAINING}
            onClick={() => setAddFilterStep("field")}
          >
            <ListFilter className="h-4 w-4" />
            Add Filter
          </Button>
        </PopoverTrigger>
        <PopoverContent
          className={cn(
            addFilterStep === "field" ? "p-0" : "min-w-64 p-3",
            "bg-card w-fit"
          )}
          align="start"
        >
          {addFilterStep === "field" ? (
            <>
              <div className="p-2 border-b border-border">
                <div className="relative">
                  <Search className="absolute left-2 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    placeholder="Search fields..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    className="h-8 pl-8"
                  />
                </div>
              </div>
              <div className="max-h-60 overflow-y-auto p-1">
                {filteredRemainingFields.map((field) => (
                  <button
                    key={field.field}
                    onClick={() => handleSelectFieldForAdd(field)}
                    className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent"
                  >
                    <span className="text-muted-foreground">
                      {TYPE_ICONS[field.type]}
                    </span>
                    <span className="flex-1 text-left">{field.fieldLabel}</span>
                  </button>
                ))}
                {filteredRemainingFields.length === 0 && (
                  <div className="py-6 text-center text-sm text-muted-foreground">
                    {search
                      ? "No fields found"
                      : "All fields are already in use"}
                  </div>
                )}
              </div>
            </>
          ) : addFilterStep === "value" && selectedFieldForAdd ? (
            <div className="space-y-3">
              <div className="flex items-center gap-2 pb-2 border-b">
                <span className="text-muted-foreground">
                  {TYPE_ICONS[selectedFieldForAdd.type]}
                </span>
                <span className="font-medium text-foreground text-sm">
                  {selectedFieldForAdd.fieldLabel}
                </span>
              </div>

              <div className="flex items-center gap-2 ">
                <div className="space-y-2 h-7">
                  <FilterOperatorSelector
                    type={selectedFieldForAdd.type}
                    isNullable={selectedFieldForAdd.isNullable}
                    selectedOperator={tempOperator}
                    onSelect={onSelectOperator}
                  />
                </div>

                {operatorRequiresValue(tempOperator) && (
                  <div className="space-y-2 flex-1 h-7">
                    {selectedFieldForAdd.type === "date" ? (
                      <FilterDateValue
                        operator={tempOperator}
                        value={tempValue as string | [string, string] | null}
                        onChange={setTempValue}
                      />
                    ) : selectedFieldForAdd.type === "boolean" ? (
                      <FilterBooleanValue
                        value={tempValue as boolean | null}
                        onChange={setTempValue}
                      />
                    ) : (
                      <FilterValueSelector
                        filter={selectedFieldForAdd}
                        operator={tempOperator}
                        value={tempValue as string | string[]}
                        onChange={setTempValue}
                      />
                    )}
                  </div>
                )}
              </div>

              <div className="flex gap-2 pt-2">
                <Button
                  variant="outline"
                  size="sm"
                  className="h-7 flex-1 text-xs"
                  onClick={handleCancelAddFilter}
                >
                  Cancel
                </Button>
                <Button
                  size="sm"
                  className="h-7 flex-1 text-xs"
                  disabled={STEP_VALUE_ADD_FILTER_BUTTON_DISABLED}
                  onClick={handleConfirmAddFilter}
                >
                  Add Filter
                </Button>
              </div>
            </div>
          ) : null}
        </PopoverContent>
      </Popover>
      <Button
        variant="outline"
        size="sm"
        className="h-8 gap-1.5"
        onClick={criteria.clearFilters}
      >
        <X className="h-4 w-4" />
        Clear Filters
      </Button>
    </div>
  );
}

"use client";

import { FilterRow } from "@/components/filter/filter-row";
import {
  type QueryFilter,
  type FilterValue,
  getDefaultOperator,
  defineDefaultFilterValue,
  operatorSupportsMultipleValues,
  operatorIsBetween,
} from "@/lib/filter-utils";
import {
  type FieldPath,
  type FilterValueFor,
  type OperatorsForType,
} from "@woltz/rich-domain";
import type { UseCriteriaReturn } from "@/types/use-criteria.type";
import { useDebounceCallback } from "@/hooks/use-debounce-callback";

interface FilterProps {
  fields: QueryFilter[];
  criteria: UseCriteriaReturn<any>; // eslint-disable-line @typescript-eslint/no-explicit-any
}

export function DataViewFilterRow({ fields, criteria }: FilterProps) {
  const filterValues: FilterValue[] = criteria.filters.map((filter) => ({
    field: filter.field,
    operator: filter.operator as FilterValue["operator"],
    value: filter.value as FilterValue["value"],
  }));

  const usedFields = criteria.filters.map((filter) => filter.field);

  const handleUpdateFilter = (index: number, newValue: FilterValue) => {
    const prevFilter = filterValues[index];
    if (!prevFilter) return;

    const newField = fields.find((f) => f.field === newValue.field);
    const prevField = fields.find((f) => f.field === prevFilter.field);
    if (!newField || !prevField) return;

    const fieldTypeChanged = prevField.type !== newField.type;

    const operator = fieldTypeChanged
      ? getDefaultOperator(newField.type)
      : newValue.operator;

    let value =
      newValue.value === null || fieldTypeChanged
        ? defineDefaultFilterValue(newField.type, newValue.operator)
        : newValue.value;

    const newOperatorIsArrayOperator = operatorSupportsMultipleValues(operator);
    const prevOperatorIsArrayOperator = operatorSupportsMultipleValues(
      prevFilter.operator
    );
    const newOperatorIsBetween = operatorIsBetween(operator);
    const prevOperatorIsBetween = operatorIsBetween(prevFilter.operator);

    if (prevOperatorIsArrayOperator && !newOperatorIsArrayOperator) {
      value = null;
    }

    if (prevOperatorIsBetween && !newOperatorIsBetween) {
      value = null;
    } else if (!prevOperatorIsBetween && newOperatorIsBetween) {
      value = newField.type === "number" ? [0, 0] : ["", ""];
    }

    criteria.addOrReplaceByIndex({
      field: newField.field as FieldPath<unknown>,
      operator: operator as OperatorsForType<never>,
      value: value as FilterValueFor<never>,
      replaceIndex: index,
    });
  };

  const [handleUpdateFilterDebounced] = useDebounceCallback(
    (index: number, newValue: FilterValue) => {
      handleUpdateFilter(index, newValue);
    },
    300
  );

  const handleSelectField = (index: number, newValue: FilterValue) => {
    const filterToUpdate = criteria.filters[index];
    if (!filterToUpdate) return;

    const newField = fields.find((f) => f.field === newValue.field);
    const oldField = fields.find((f) => f.field === filterToUpdate.field);

    if (!newField || !oldField) return;

    let value = filterToUpdate.value;
    let operator = newValue.operator;

    if (newField.type !== oldField.type) {
      operator = getDefaultOperator(newField.type);
      value = defineDefaultFilterValue(newField.type);
    }

    criteria.addOrReplaceByIndex({
      field: newValue.field as FieldPath<unknown>,
      operator: operator as OperatorsForType<never>,
      value: value as FilterValueFor<never>,
      replaceIndex: index,
    });
  };

  const handleRemoveFilter = (index: number) => {
    criteria.removeFilter(index);
  };

  return (
    <div className="space-y-2">
      {filterValues.map((filter, index) => (
        <FilterRow
          key={`${filter.field}-${index}`}
          fields={fields}
          value={filter}
          onChange={(newValue) => handleUpdateFilterDebounced(index, newValue)}
          onSelectField={(newValue) => handleSelectField(index, newValue)}
          onRemove={() => handleRemoveFilter(index)}
          usedFields={usedFields}
        />
      ))}
    </div>
  );
}

import { useCallback, useEffect, useMemo } from "react";
import { useCriteriaInfiniteQuery } from "./use-criteria-infinite-query";
import type {
  Criteria,
  FieldPath,
  PaginatedJsonResult,
} from "@woltz/rich-domain";
import type {
  UseCriteriaTimelineOptions,
  UseCriteriaTimelineReturn,
  TimelineGroup,
  TimelineGroupBy,
} from "../types/use-criteria-timeline.type";
import { useDebounceCallback } from "./use-debounce-callback";
import {
  format,
  startOfDay,
  startOfWeek,
  startOfMonth,
  startOfYear,
  startOfHour,
  formatDistanceToNow,
  isToday,
  isYesterday,
  isThisWeek,
  isThisMonth,
  isThisYear,
} from "date-fns";

function getStartOfPeriod(date: Date, groupBy: TimelineGroupBy): Date {
  switch (groupBy) {
    case "hour":
      return startOfHour(date);
    case "day":
      return startOfDay(date);
    case "week":
      return startOfWeek(date);
    case "month":
      return startOfMonth(date);
    case "year":
      return startOfYear(date);
  }
}

function formatGroupLabel(date: Date, groupBy: TimelineGroupBy): string {
  switch (groupBy) {
    case "hour":
      return format(date, "MMMM d, yyyy 'at' h:mm a");
    case "day":
      return format(date, "MMMM d, yyyy");
    case "week":
      return format(date, "'Week of' MMMM d, yyyy");
    case "month":
      return format(date, "MMMM yyyy");
    case "year":
      return format(date, "yyyy");
  }
}

function getRelativeLabel(date: Date, groupBy: TimelineGroupBy): string {
  if (groupBy === "hour") {
    return formatDistanceToNow(date, { addSuffix: true });
  }

  if (groupBy === "day") {
    if (isToday(date)) return "Today";
    if (isYesterday(date)) return "Yesterday";
    if (isThisWeek(date)) return format(date, "EEEE"); // Day name
  }

  if (groupBy === "week") {
    if (isThisWeek(date)) return "This Week";
  }

  if (groupBy === "month") {
    if (isThisMonth(date)) return "This Month";
  }

  if (groupBy === "year") {
    if (isThisYear(date)) return "This Year";
  }

  return formatDistanceToNow(date, { addSuffix: true });
}

function groupDataByTime<T>(
  data: T[],
  dateField: FieldPath<T>,
  groupBy: TimelineGroupBy
): TimelineGroup<T>[] {
  const groups = new Map<string, TimelineGroup<T>>();

  for (const item of data) {
    const dateValue = (item as never)[dateField];
    if (!dateValue) continue;

    const date = new Date(dateValue);
    if (isNaN(date.getTime())) {
      console.warn(`Invalid date value for item: ${dateValue}`);
      continue;
    }

    const periodStart = getStartOfPeriod(date, groupBy);
    const key = periodStart.toISOString();

    let group = groups.get(key);
    if (!group) {
      group = {
        date: key,
        label: formatGroupLabel(periodStart, groupBy),
        relativeLabel: getRelativeLabel(periodStart, groupBy),
        items: [],
      };
      groups.set(key, group);
    }

    group.items.push(item);
  }

  return Array.from(groups.values()).sort(
    (a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()
  );
}

/**
 * Hook for timeline view with date-based grouping
 *
 * Extends useCriteriaQuery with automatic date sorting and grouping.
 * Groups items by time periods (hour/day/week/month/year) and provides
 * relative time labels.
 *
 * @example
 * ```tsx
 * const timeline = useCriteriaTimeline({
 *   queryKey: ['activities'],
 *   queryFn: getActivities,
 *   dateField: 'createdAt',
 *   groupBy: 'day',
 *   filterFields,
 * });
 *
 * return (
 *   <DataTimelineCriteria
 *     timeline={timeline}
 *     renderEvent={(activity) => <ActivityCard {...activity} />}
 *   />
 * );
 * ```
 */
export function useCriteriaTimeline<T>(
  queryKey: string | readonly unknown[],
  queryFn: (criteria: Criteria<T>) => Promise<PaginatedJsonResult<T>>,
  options: UseCriteriaTimelineOptions<T>
): UseCriteriaTimelineReturn<T> {
  const {
    dateField,
    groupBy = "day",
    sortDirection = "desc",
    filterFields = [],
    searchDebounceMs = 500,
    ...queryOptions
  } = options;

  const queryResult = useCriteriaInfiniteQuery<T>(queryKey, queryFn, {
    ...queryOptions,
    initialSort: [{ field: dateField, direction: sortDirection }],
  });
  const { criteria } = queryResult;

  useEffect(() => {
    if (
      criteria.sorting.length === 0 ||
      criteria.sorting[0]?.field !== dateField
    ) {
      criteria.addSort(dateField, sortDirection);
    }
    // Do not have sorting button so we don't need to re-add the sort when the sorting changes
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dateField, sortDirection]);

  const groupedData = useMemo(() => {
    return groupDataByTime(queryResult.data, dateField, groupBy);
  }, [queryResult.data, dateField, groupBy]);

  const [debouncedSetSearch] = useDebounceCallback((value: string) => {
    criteria.setSearch(value);
  }, searchDebounceMs);

  const handleSearchChange = useCallback(
    (value: string) => {
      debouncedSetSearch(value);
    },
    [debouncedSetSearch]
  );

  const searchProps = useMemo(
    () => ({
      searchValue: criteria.search || "",
      onSearchChange: handleSearchChange,
      showSearch: true,
    }),
    [criteria.search, handleSearchChange]
  );

  const loadMore = useCallback(() => {
    if (queryResult.hasNextPage && !queryResult.isFetchingNextPage) {
      queryResult.fetchNextPage();
    }
  }, [queryResult]);

  const hasMore = queryResult.hasNextPage;
  const isLoadingMore = queryResult.isFetchingNextPage;

  return {
    ...queryResult,
    groupedData,
    dateField,
    groupBy,
    filterProps: {
      queryFilter: filterFields,
      criteria,
    },
    searchProps,
    loadMore,
    hasMore,
    isLoadingMore,
    isRefetching: queryResult.isFetching,
  };
}
